const canAddMore = (id) => {
const product = products.find(p => String(p.id) === String(id));
const stock = Number(product?.stockLeft || 0);
const limit = getLimit(product);
const currentQty = getQty(id);
return currentQty < stock && currentQty < limit;
};

const handleAddClick = (id) => {
const product = products.find(p => String(p.id) === String(id));
const stock = Number(product?.stockLeft || 0);
const limit = getLimit(product);
if (stock <= 0) return; 
if(limit <= 0) return;
// handleAdd(id);
setCart(prev => ({ ...prev, [id]: 1}));
setChecked(true);
};

const getLimit = (product) => {
if (!product) return Infinity;
const apiLimit = Number(product.limit);
if (Number.isFinite(apiLimit) && apiLimit > 0) {
return apiLimit;
}
return Infinity;
};

function getItemTime(p) {
if (p?.date) {
const t = Date.parse(p.date); 
if (!Number.isNaN(t)) return t;
}

const candidates = [
p.createdAt, p.created_on, p.createdDate, p.createDate,
p.updatedAt, p.updated_on, p.modifiedAt, p.modified_on,
p.addedDate, p.added_at, p.timestamp, p.timeStamp,
];
for (const c of candidates) {
const t = Date.parse(c);
if (!Number.isNaN(t)) return t;
}

if (typeof p.id === "number") return p.id;
const idNum = Number(String(p.id || "").replace(/\D/g, "")) || 0;
return idNum;
}

